import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { respondQuiz } from "../handlers/respondQuiz";
import type { ApiError } from "../runtime/client";
import type { RespondQuizRequest } from "../types/RespondQuizRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpaceQuizEntityType } from "../types/SpaceQuizEntityType";

type Data = Awaited<ReturnType<typeof respondQuiz>>;
type Vars = { spacePk: SpacePartition; quizId: SpaceQuizEntityType; req: RespondQuizRequest };

export function useRespondQuiz(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => respondQuiz(vars.spacePk, vars.quizId, vars.req),
    ...options,
  });
}
